ALTER TABLE asset_version ADD COLUMN processing_requirement TEXT NOT NULL DEFAULT 'legacy' CHECK(processing_requirement IN ('legacy','package-replay-v1'));
ALTER TABLE asset_version ADD COLUMN processing_policy_version TEXT NOT NULL DEFAULT 'legacy';
CREATE TRIGGER immutable_processing_requirement BEFORE UPDATE OF processing_requirement,processing_policy_version ON asset_version BEGIN SELECT RAISE(ABORT,'immutable_processing_requirement'); END;
CREATE TABLE processor(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES member(user_id),label TEXT NOT NULL,profiles TEXT NOT NULL CHECK(json_valid(profiles)),secret_hash TEXT NOT NULL UNIQUE,enabled INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN (0,1)),created_at INTEGER NOT NULL);
CREATE TABLE processing_profile(id TEXT PRIMARY KEY,profile TEXT NOT NULL,policy_version TEXT NOT NULL,configuration TEXT NOT NULL CHECK(json_valid(configuration)),enabled INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN (0,1)));
CREATE TRIGGER immutable_processing_profile BEFORE UPDATE OF id,profile,policy_version,configuration ON processing_profile BEGIN SELECT RAISE(ABORT,'immutable_processing_profile'); END;
CREATE UNIQUE INDEX active_processing_profile ON processing_profile(profile,policy_version) WHERE enabled=1;
CREATE TABLE processing_job(id TEXT PRIMARY KEY,version_id TEXT NOT NULL UNIQUE REFERENCES asset_version(id),profile TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','running','passed','failed','exhausted')),attempts INTEGER NOT NULL DEFAULT 0 CHECK(attempts BETWEEN 0 AND 3),current_attempt TEXT,technical_record_id TEXT,first_failure TEXT,created_at INTEGER NOT NULL);
CREATE TABLE processing_attempt(id TEXT PRIMARY KEY,job_id TEXT NOT NULL REFERENCES processing_job(id),processor_id TEXT NOT NULL REFERENCES processor(id),claim_key TEXT NOT NULL,lease_id TEXT NOT NULL,lease_expires_at INTEGER NOT NULL,profile_id TEXT NOT NULL REFERENCES processing_profile(id),result TEXT,result_hash TEXT,created_at INTEGER NOT NULL,UNIQUE(processor_id,claim_key));
CREATE UNIQUE INDEX processor_live_claim ON processing_attempt(processor_id) WHERE result IS NULL;
CREATE TABLE processing_artifact(attempt_id TEXT NOT NULL REFERENCES processing_attempt(id),path TEXT NOT NULL,sha256 TEXT NOT NULL,bytes INTEGER NOT NULL CHECK(bytes BETWEEN 0 AND 2097152),media_type TEXT NOT NULL,failure_revision INTEGER NOT NULL DEFAULT 0,verified_revision INTEGER,PRIMARY KEY(attempt_id,path));
CREATE TABLE processing_receipt(attempt_id TEXT NOT NULL,path TEXT NOT NULL,sha256 TEXT NOT NULL,bytes INTEGER NOT NULL,failure_revision INTEGER NOT NULL,verified_at INTEGER NOT NULL,PRIMARY KEY(attempt_id,path,failure_revision),FOREIGN KEY(attempt_id,path) REFERENCES processing_artifact(attempt_id,path));
CREATE TABLE processing_attestation(record_id TEXT PRIMARY KEY,version_id TEXT NOT NULL REFERENCES asset_version(id),attempt_id TEXT NOT NULL UNIQUE REFERENCES processing_attempt(id),reviewer_id TEXT NOT NULL,record TEXT NOT NULL CHECK(json_valid(record)),created_at INTEGER NOT NULL);
CREATE TRIGGER immutable_processing_artifact BEFORE UPDATE OF attempt_id,path,sha256,bytes,media_type ON processing_artifact BEGIN SELECT RAISE(ABORT,'immutable_processing_artifact'); END;
CREATE TRIGGER immutable_processing_receipt BEFORE UPDATE ON processing_receipt BEGIN SELECT RAISE(ABORT,'immutable_processing_receipt'); END;
CREATE TRIGGER no_processing_receipt_delete BEFORE DELETE ON processing_receipt BEGIN SELECT RAISE(ABORT,'immutable_processing_receipt'); END;
CREATE TRIGGER immutable_processing_result BEFORE UPDATE OF result,result_hash ON processing_attempt WHEN OLD.result IS NOT NULL BEGIN SELECT RAISE(ABORT,'immutable_processing_result'); END;
CREATE TRIGGER immutable_processing_attestation BEFORE UPDATE ON processing_attestation BEGIN SELECT RAISE(ABORT,'immutable_processing_attestation'); END;
CREATE TRIGGER no_processing_attestation_delete BEFORE DELETE ON processing_attestation BEGIN SELECT RAISE(ABORT,'immutable_processing_attestation'); END;
CREATE TRIGGER processing_revision AFTER INSERT ON processing_attestation BEGIN UPDATE asset_version SET review_revision=review_revision+1 WHERE id=NEW.version_id; END;
CREATE TRIGGER processor_epoch AFTER UPDATE ON processor BEGIN UPDATE authority_policy SET epoch=epoch+1 WHERE id=1; END;
CREATE TRIGGER processing_profile_epoch AFTER UPDATE ON processing_profile BEGIN UPDATE authority_policy SET epoch=epoch+1 WHERE id=1; END;
CREATE TRIGGER processing_revocation AFTER INSERT ON record_revocation BEGIN UPDATE asset_version SET state='withdrawn' WHERE state IN ('approved','published') AND id IN (SELECT version_id FROM processing_attestation WHERE record_id=NEW.record_id); END;
DROP TRIGGER version_state_machine;
CREATE TRIGGER version_state_machine BEFORE UPDATE OF state ON asset_version WHEN OLD.state!=NEW.state AND NOT ((OLD.state='draft' AND NEW.state IN ('submitted','withdrawn')) OR (OLD.state='submitted' AND NEW.state IN ('processing','withdrawn')) OR (OLD.state='processing' AND NEW.state IN ('submitted','changes_requested','awaiting_review','withdrawn')) OR (OLD.state='awaiting_review' AND NEW.state IN ('changes_requested','rejected','approved','withdrawn')) OR (OLD.state='changes_requested' AND NEW.state IN ('submitted','withdrawn')) OR (OLD.state='rejected' AND NEW.state='withdrawn') OR (OLD.state='approved' AND NEW.state IN ('published','withdrawn')) OR (OLD.state='published' AND NEW.state='withdrawn')) BEGIN SELECT RAISE(ABORT,'invalid_version_transition'); END;
CREATE TRIGGER no_manual_required_attestation BEFORE INSERT ON technical_attestation WHEN (SELECT processing_requirement FROM asset_version WHERE id=NEW.version_id)!='legacy' BEGIN SELECT RAISE(ABORT,'isolated_processing_required'); END;
CREATE TRIGGER immutable_processing_attempt BEFORE UPDATE OF id,job_id,processor_id,claim_key,lease_id,profile_id,created_at ON processing_attempt BEGIN SELECT RAISE(ABORT,'immutable_processing_attempt'); END;
CREATE TRIGGER no_processing_attempt_delete BEFORE DELETE ON processing_attempt BEGIN SELECT RAISE(ABORT,'immutable_processing_attempt'); END;
CREATE TRIGGER no_processing_artifact_delete BEFORE DELETE ON processing_artifact BEGIN SELECT RAISE(ABORT,'immutable_processing_artifact'); END;
CREATE TRIGGER immutable_processing_job BEFORE UPDATE OF id,version_id,profile,created_at ON processing_job BEGIN SELECT RAISE(ABORT,'immutable_processing_job'); END;
